runner.program:
"""CF2A-01 conformance bundle runner.

Usage, from the repository root:

    python3 docs/handbook/conformance/run.py
    python3 -c "<this program>" docs/handbook/conformance/manifest.json

It reads the manifest, then:
  1. verifies the pinned digest of the model, the vectors, every schema and every fixture,
  2. validates each positive binding with the schema it names,
  3. applies each negative arm and asserts the schema refuses the mutated record,
  4. recomputes each digest check from the fixture bytes,
  5. prints one line per failure and a final verdict.

Exit 0 means every pinned digest matched, every positive binding validated and every
negative arm was refused. Exit 1 means at least one of those did not hold.
Requires jsonschema >= 4.18 for the schema steps.
"""
import copy
import hashlib
import json
import pathlib
import sys

try:
    import jsonschema
except ImportError:
    print("FAIL jsonschema is required (pip install 'jsonschema>=4.18')")
    sys.exit(1)


def jcs(obj):
    return json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def sha(text):
    return hashlib.sha256(text.encode("utf-8")).hexdigest()


def resolve(node, pointer):
    cur = node
    for part in [p for p in pointer.split("/") if p]:
        part = part.replace("~1", "/").replace("~0", "~")
        cur = cur[int(part)] if isinstance(cur, list) else cur[part]
    return cur


def apply_arm(doc, arm):
    node = copy.deepcopy(doc)
    op = arm["op"]
    if op == "set":
        resolve(node, arm["parent"])[arm["key"]] = arm["value"]
    elif op == "remove":
        resolve(node, arm["parent"]).pop(arm["key"], None)
    elif op == "array-repeat":
        items = resolve(node, arm["pointer"])
        template = items[0]
        built = []
        for i in range(arm["count"]):
            item = copy.deepcopy(template)
            item["task_id"] = "CF-%04d" % i
            built.append(item)
        parent, _, leaf = arm["pointer"].rpartition("/")
        if parent:
            resolve(node, parent)[leaf] = built
        else:
            node[leaf] = built
    elif op == "array-reverse":
        items = list(resolve(node, arm["pointer"]))
        parent, _, leaf = arm["pointer"].rpartition("/")
        if parent:
            resolve(node, parent)[leaf] = list(reversed(items))
        else:
            node[leaf] = list(reversed(items))
    else:
        raise SystemExit("unknown mutation op: " + op)
    return node


def main():
    target = sys.argv[1] if len(sys.argv) > 1 else "docs/handbook/conformance/manifest.json"
    manifest_path = pathlib.Path(target).resolve()
    manifest = json.loads(manifest_path.read_text())
    bundle_dir = manifest_path.parent
    root = bundle_dir.parents[2]
    fails = []

    def fail(msg):
        fails.append(msg)

    # 1. pinned digests
    pinned = [manifest["normative_sources"]["model"], manifest["normative_sources"]["vectors"]]
    pinned += manifest["schemas"] + manifest["fixtures"]
    for entry in pinned:
        path = root / entry["path"]
        if not path.exists():
            fail("missing artifact: " + entry["path"])
            continue
        actual = hashlib.sha256(path.read_bytes()).hexdigest()
        if actual != entry["sha256"]:
            fail("digest drift: %s expected %s got %s" % (entry["path"], entry["sha256"], actual))

    # 2. positive bindings
    validators = {}
    for entry in manifest["schemas"]:
        name = entry["path"].rsplit("/", 1)[-1]
        validators[name] = jsonschema.Draft202012Validator(json.loads((root / entry["path"]).read_text()))
    fixtures = {}
    for entry in manifest["fixtures"]:
        name = entry["path"].rsplit("/", 1)[-1]
        fixtures[name] = json.loads((root / entry["path"]).read_text())

    for b in manifest["bindings"]:
        doc = resolve(fixtures[b["fixture"]], b["pointer"])
        errs = list(validators[b["schema"]].iter_errors(doc))
        if b["expect"] == "pass" and errs:
            fail("binding %s%s vs %s: %s" % (b["fixture"], b["pointer"], b["schema"], errs[0].message))
        if b["expect"] == "fail" and not errs:
            fail("binding %s%s vs %s accepted a record it must refuse" % (b["fixture"], b["pointer"], b["schema"]))

    # 3. negative arms
    for arm in manifest["negative_arms"]:
        if arm["kind"] != "schema":
            continue
        base = resolve(fixtures[arm["fixture"]], arm.get("base", "/"))
        doc = apply_arm(base, arm)
        if not list(validators[arm["schema"]].iter_errors(doc)):
            fail("negative arm %r was accepted by %s" % (arm["name"], arm["schema"]))

    # 4. digest recomputation
    for chk in manifest["digest_checks"]:
        prefix = chk.get("prefix") or ""
        if chk.get("kind") == "derived":
            got = prefix + sha("".join(chk["concat"]))
        else:
            obj = resolve(fixtures[chk["fixture"]], chk["object"])
            if obj is None:
                fail("digest check %s: object %s is absent" % (chk["name"], chk["object"]))
                continue
            if chk.get("exclude"):
                obj = {k: v for k, v in obj.items() if k not in chk["exclude"]}
            got = prefix + sha((chk.get("tag") or "") + jcs(obj))
        if got != chk["value"]:
            fail("digest %s: expected %s got %s" % (chk["name"], chk["value"], got))

    if fails:
        for f in fails:
            print("FAIL " + f)
        print("conformance bundle: %d failure(s)" % len(fails))
        return 1
    print("conformance bundle: clean — %d pinned artifacts, %d bindings, %d negative arms, %d digest checks"
          % (len(pinned), len(manifest["bindings"]), len(manifest["negative_arms"]), len(manifest["digest_checks"])))
    return 0


if __name__ == "__main__":
    sys.exit(main())
